<section class="auth-card"><div class="eyebrow">خوش آمدید</div><h1>ورود به حساب کاربری</h1><p class="muted">ادامه‌ی مسیرتان را از همین‌جا دنبال کنید.</p><?php if ($message = Session::flash('success')): ?><div class="alert success"><?= e($message) ?></div><?php endif; ?><?php if ($message = Session::flash('error')): ?><div class="alert error"><?= e($message) ?></div><?php endif; ?><form method="post" action="<?= url('/login') ?>"><?= csrf_field() ?><label>ایمیل<input type="email" name="email" required autocomplete="email"></label><label>رمز عبور<input type="password" name="password" required autocomplete="current-password"></label><div class="form-row"><label class="check"><input type="checkbox" name="remember"> مرا به خاطر بسپار</label><a href="#">رمز عبور را فراموش کرده‌اید؟</a></div><button class="button full" type="submit">ورود <span>↗</span></button></form><p class="form-footer">هنوز حساب ندارید؟ <a href="<?= url('/register') ?>">ثبت‌نام کنید</a></p></section>
